const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // A1 portrait: 594 x 841 pixels at 72dpi
  await page.setViewportSize({ width: 594, height: 841 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(2000);

  // Export SVG from the infographic
  const svgDataUrl = await page.evaluate(async () => {
    const containers = document.querySelectorAll('#container');
    if (containers[0] && containers[0].__infographic) {
      return await containers[0].__infographic.toDataURL({ type: 'svg' });
    }
    // Fallback: get SVG directly
    const svg = containers[0]?.querySelector('svg');
    return svg ? 'data:image/svg+xml;base64,' + btoa(svg.outerHTML) : null;
  });

  if (svgDataUrl) {
    // Save SVG
    const base64 = svgDataUrl.replace(/^data:image\/svg\+xml;base64,/, '');
    require('fs').writeFileSync('/app/output/final_poster.svg', Buffer.from(base64, 'base64'));
    console.log('SVG saved to /app/output/final_poster.svg');

    // Also try to get PNG if infographic supports it
    const pngDataUrl = await page.evaluate(async () => {
      const containers = document.querySelectorAll('#container');
      if (containers[0] && containers[0].__infographic) {
        return await containers[0].__infographic.toDataURL({ type: 'png' });
      }
      return null;
    });

    if (pngDataUrl) {
      const pngBase64 = pngDataUrl.replace(/^data:image\/png;base64,/, '');
      require('fs').writeFileSync('/app/output/final_poster.png', Buffer.from(pngBase64, 'base64'));
      console.log('PNG saved to /app/output/final_poster.png');
    }
  }

  await browser.close();
  console.log('Done');
})();

