const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();

  // A1 portrait: 594 x 841 pixels at 72dpi
  await page.setViewportSize({ width: 794, height: 1123 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(3000);

  // Export SVG from the infographic
  const result = await page.evaluate(async () => {
    const inf = window._infographic;
    if (!inf) return { error: 'No infographic instance found' };

    try {
      const svgDataUrl = await inf.toDataURL({ type: 'svg' });
      return { svgDataUrl };
    } catch (e) {
      return { error: e.message };
    }
  });

  console.log('Result:', JSON.stringify(result));

  if (result.svgDataUrl) {
    // Save SVG
    const base64 = result.svgDataUrl.replace(/^data:image\/svg\+xml;base64,/, '');
    require('fs').writeFileSync('/app/output/final_poster.svg', Buffer.from(base64, 'base64'));
    console.log('SVG saved to /app/output/final_poster.svg');

    // Try PNG via canvas conversion
    try {
      const pngDataUrl = await inf.toDataURL({ type: 'png' });
      if (pngDataUrl) {
        const pngBase64 = pngDataUrl.replace(/^data:image\/png;base64,/, '');
        require('fs').writeFileSync('/app/output/final_poster.png', Buffer.from(pngBase64, 'base64'));
        console.log('PNG saved to /app/output/final_poster.png');
      }
    } catch (e) {
      console.log('PNG export not supported, trying canvas fallback');
    }
  } else if (result.error) {
    console.error('Error:', result.error);
  }

  await browser.close();
  console.log('Done');
})();

