const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome'
  });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 794, height: 1123 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(3000);

  // Get SVG data from the infographic
  const result = await page.evaluate(async () => {
    const inf = window._infographic;
    if (!inf) return { error: 'No infographic instance found' };

    try {
      const svgDataUrl = await inf.toDataURL({ type: 'svg' });
      return { svgDataUrl };
    } catch (e) {
      return { error: e.message };
    }
  });

  console.log('Got result, length:', result.svgDataUrl ? result.svgDataUrl.length : 'no data');

  if (result.svgData && result.svgData.length > 100) {
    const base64 = result.svgData.replace(/^data:image\/svg\+xml;base64,/, '');
    fs.writeFileSync('/app/output/final_poster.svg', Buffer.from(base64, 'base64'));
    console.log('SVG saved');
  } else if (result.svgDataUrl && result.svgDataUrl.length > 100) {
    // Try to extract base64 from the URL
    const match = result.svgDataUrl.match(/,([A-Za-z0-9+/=]+)$/);
    if (match) {
      const base64 = match[1];
      fs.writeFileSync('/app/output/final_poster.svg', Buffer.from(base64, 'base64'));
      console.log('SVG saved from match, size:', fs.statSync('/app/output/final_poster.svg').size);
    }
  } else if (result.error) {
    console.error('Error:', result.error);
  } else {
    console.log('Result object:', JSON.stringify(result).substring(0, 500));
  }

  await browser.close();
  console.log('Done');
})();

