const { chromium } = require('playwright');
const fs = require('fs');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome'
  });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 794, height: 1123 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(3000);

  // Get SVG data from the infographic
  const result = await page.evaluate(async () => {
    const inf = window._infographic;
    if (!inf) return { error: 'No infographic instance found' };

    try {
      const svgDataUrl = await inf.toDataURL({ type: 'svg' });
      // Return the actual data portion for base64
      return svgDataUrl;
    } catch (e) {
      return { error: e.message };
    }
  });

  if (result && typeof result === 'string' && result.startsWith('data:image/svg')) {
    const commaIndex = result.indexOf(',');
    if (commaIndex !== -1) {
      const base64 = result.substring(commaIndex + 1);
      fs.writeFileSync('/app/output/final_poster.svg', Buffer.from(base64, 'base64'));
      console.log('SVG saved, size:', fs.statSync('/app/output/final_poster.svg').size);
    }
  } else if (result && result.error) {
    console.error('Error:', result.error);
  } else {
    console.log('Unexpected result type:', typeof result);
    if (result && result.substring) {
      console.log('First 100 chars:', result.substring(0, 100));
    }
  }

  await browser.close();
  console.log('Done');
})();

