(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome'
  });
  const page = await browser.newPage();

  await page.setViewportSize({ width: 794, height: 1123 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(3000);

  // Get the raw SVG element
  const svgContent = await page.evaluate(async () => {
    const svg = document.querySelector('#container svg');
    if (svg) {
      const serializer = new XMLSerializer();
      return serializer.serializeToString(svg);
    }
    return null;
  });

  if (svgContent) {
    fs.writeFileSync('/app/output/final_poster.svg', svgContent, 'utf8');
    console.log('SVG saved directly, size:', fs.statSync('/app/output/final_poster.svg').size);
  } else {
    console.log('No SVG found');
  }

  await browser.close();
  console.log('Done');
})();

