    executablePath: '/root/.cache/ms-playwright/chromium-1148/chrome-linux/chrome'
  });
  const page = await browser.newPage();

  // A1 portrait: 594 x 841 pt at 72dpi, but at 2x for retina quality = 1188 x 1682
  await page.setViewportSize({ width: 1188, height: 1682 });

  await page.goto('file:///app/output/GlobalEconomicProspects-infographic.html');
  await page.waitForTimeout(3000);

  // Screenshot the page to get PNG
  const screenshot = await page.screenshot({ type: 'png', fullPage: false });
  fs.writeFileSync('/app/output/final_poster.png', screenshot);
  console.log('PNG saved, size:', fs.statSync('/app/output/final_poster.png').size);

  // Also save the raw SVG
  const svgContent = await page.evaluate(async () => {
    const svg = document.querySelector('#container svg');
    if (svg) {
      const serializer = new XMLSerializer();
      return serializer.serializeToString(svg);
    }
    return null;
  });

  if (svgContent) {
    fs.writeFileSync('/app/output/final_poster.svg', svgContent, 'utf8');
    console.log('SVG also saved');
  }

  await browser.close();
  console.log('Done');
})();

